import { useState, useEffect } from 'react';

interface Profile {
  id: number;
  name: string;
  role: string;
}

export default function ProfileWidget() {
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadProfile = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('http://localhost:4000/api/profile');
      if (!res.ok) {
        throw new Error('Failed to load profile');
      }
      const data = (await res.json()) as Profile;
      setProfile(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
      setProfile(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadProfile();
  }, []);

  if (loading) {
    return <div className="profile-widget loading">Loading profile...</div>;
  }

  if (error) {
    return (
      <div className="profile-widget error">
        <p>Error: {error}</p>
        <button onClick={loadProfile}>Retry</button>
      </div>
    );
  }

  if (!profile) {
    return (
      <div className="profile-widget empty">
        <p>No profile loaded.</p>
        <button onClick={loadProfile}>Load profile</button>
      </div>
    );
  }

  return (
    <div className="profile-widget loaded">
      <h1>Profile Widget</h1>
      <h2>{profile.name}</h2>
      <p>Role: {profile.role}</p>
      <button onClick={loadProfile}>Refresh</button>
    </div>
  );
}
